import React, { useState } from 'react';
import { loginUser, signupUser, supabase } from './supabase';

function Login({ onLogin }) {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [isSignup, setIsSignup] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [otpSent, setOtpSent] = useState(false);
  const [otp, setOtp] = useState('');
  const [otpEmail, setOtpEmail] = useState('');

  const handleSubmit = async () => {
    if (!email || !password) return setError('Please fill in all fields');
    setLoading(true);
    setError('');
    try {
      if (isSignup) {
        await signupUser(email, password);
        setError('✅ Check your email to confirm your account!');
      } else {
        // Login then send OTP
        const data = await loginUser(email, password);
        if (data.user) {
          // Send OTP to email
          await supabase.auth.signOut();
          const { error: otpError } = await supabase.auth.signInWithOtp({ email });
          if (otpError) throw otpError;
          setOtpEmail(email);
          setOtpSent(true);
        }
      }
    } catch (err) {
      setError(err.message);
    }
    setLoading(false);
  };

  const handleVerifyOtp = async () => {
    if (!otp) return setError('Please enter the OTP');
    setLoading(true);
    setError('');
    try {
      const { data, error } = await supabase.auth.verifyOtp({
        email: otpEmail,
        token: otp,
        type: 'email'
      });
      if (error) throw error;
      onLogin(data.user);
    } catch (err) {
      setError(err.message);
    }
    setLoading(false);
  };

  if (otpSent) return (
    <div style={{ minHeight: '100vh', background: '#0f172a', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
      <div style={{ background: '#1e293b', padding: '40px', borderRadius: '12px', width: '100%', maxWidth: '400px' }}>
        <h1 style={{ textAlign: 'center', color: '#60a5fa', marginTop: 0 }}>✨ ContentAI</h1>
        <h2 style={{ textAlign: 'center', color: 'white', marginTop: 0 }}>Check Your Email</h2>
        <p style={{ color: '#94a3b8', textAlign: 'center', fontSize: '14px' }}>
          We sent a 6-digit OTP to <strong style={{ color: 'white' }}>{otpEmail}</strong>
        </p>

        {error && (
          <div style={{ background: '#450a0a', color: '#fca5a5', padding: '12px', borderRadius: '8px', marginBottom: '16px', fontSize: '14px' }}>
            {error}
          </div>
        )}

        <input
          type="text"
          placeholder="Enter 6-digit OTP"
          value={otp}
          onChange={(e) => setOtp(e.target.value)}
          maxLength={6}
          style={{ width: '100%', padding: '12px', background: '#0f172a', border: '1px solid #334155', borderRadius: '8px', color: 'white', fontSize: '20px', marginBottom: '16px', boxSizing: 'border-box', textAlign: 'center', letterSpacing: '8px' }}
        />

        <button
          onClick={handleVerifyOtp}
          disabled={loading}
          style={{ width: '100%', padding: '12px', background: loading ? '#475569' : '#3b82f6', color: 'white', border: 'none', borderRadius: '8px', fontSize: '16px', cursor: loading ? 'not-allowed' : 'pointer' }}
        >
          {loading ? '⏳ Verifying...' : '✅ Verify OTP'}
        </button>

        <p style={{ textAlign: 'center', color: '#94a3b8', marginTop: '16px', fontSize: '14px' }}>
          Didn't get it?
          <span onClick={handleSubmit} style={{ color: '#60a5fa', cursor: 'pointer', marginLeft: '6px' }}>
            Resend OTP
          </span>
        </p>
      </div>
    </div>
  );

  return (
    <div style={{ minHeight: '100vh', background: '#0f172a', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
      <div style={{ background: '#1e293b', padding: '40px', borderRadius: '12px', width: '100%', maxWidth: '400px' }}>
        
        <h1 style={{ textAlign: 'center', color: '#60a5fa', marginTop: 0 }}>✨ ContentAI</h1>
        <h2 style={{ textAlign: 'center', color: 'white', marginTop: 0 }}>
          {isSignup ? 'Create Account' : 'Welcome Back'}
        </h2>

        {error && (
          <div style={{ background: error.includes('✅') ? '#064e3b' : '#450a0a', color: error.includes('✅') ? '#6ee7b7' : '#fca5a5', padding: '12px', borderRadius: '8px', marginBottom: '16px', fontSize: '14px' }}>
            {error}
          </div>
        )}

        <input
          type="email"
          placeholder="Email address"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          style={{ width: '100%', padding: '12px', background: '#0f172a', border: '1px solid #334155', borderRadius: '8px', color: 'white', fontSize: '14px', marginBottom: '12px', boxSizing: 'border-box' }}
        />

        {/* Password with eye toggle */}
        <div style={{ position: 'relative', marginBottom: '16px' }}>
          <input
            type={showPassword ? 'text' : 'password'}
            placeholder="Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            style={{ width: '100%', padding: '12px', paddingRight: '44px', background: '#0f172a', border: '1px solid #334155', borderRadius: '8px', color: 'white', fontSize: '14px', boxSizing: 'border-box' }}
          />
          <span
            onClick={() => setShowPassword(!showPassword)}
            style={{ position: 'absolute', right: '12px', top: '50%', transform: 'translateY(-50%)', cursor: 'pointer', fontSize: '18px' }}
          >
            {showPassword ? '🙈' : '👁️'}
          </span>
        </div>

        <button
          onClick={handleSubmit}
          disabled={loading}
          style={{ width: '100%', padding: '12px', background: loading ? '#475569' : '#3b82f6', color: 'white', border: 'none', borderRadius: '8px', fontSize: '16px', cursor: loading ? 'not-allowed' : 'pointer' }}
        >
          {loading ? '⏳ Please wait...' : isSignup ? '🚀 Create Account' : '🔑 Login'}
        </button>

        <p style={{ textAlign: 'center', color: '#94a3b8', marginTop: '16px', fontSize: '14px' }}>
          {isSignup ? 'Already have an account?' : "Don't have an account?"}
          <span
            onClick={() => { setIsSignup(!isSignup); setError(''); }}
            style={{ color: '#60a5fa', cursor: 'pointer', marginLeft: '6px' }}
          >
            {isSignup ? 'Login' : 'Sign up'}
          </span>
        </p>
      </div>
    </div>
  );
}

export default Login;
